class ROOT(object):
    """A sentinel object representing the root of the target data being processed.

    This is useful for specs that need to refer back to the original target 
    from within nested specifications.

    Example:
        >>> target = {'a': {'b': 1}}
        >>> glom(target, {'root': ROOT, 'nested': 'a.b'})
        {'root': {'a': {'b': 1}}, 'nested': 1}

    """
    pass


class Auto(object):
    """Auto specifier type that enables automatic spec processing.

    Similar to how dicts, lists, and tuples work automatically as specs,
    Auto can be used explicitly when you need this behavior in a context
    where it might not be assumed.

    Args:
       spec: The specification to process with auto-behavior.

    """
    def __init__(self, spec=None):
        self.spec = spec

    def glomit(self, target, scope):
        if self.spec is None:
            return target
        return scope[glom](target, self.spec, scope)

    def __repr__(self):
        cn = self.__class__.__name__
        if self.spec is None:
            return '%s()' % (cn,)
        return '%s(%r)' % (cn, self.spec)


class Fill(object):
    """Fill specifier type for filling in missing values with defaults.

    When a value is missing or None, Fill will substitute a default value.

    Args:
       spec: The specification to apply.
       default: The default value to use if the spec returns None or is missing.

    Example:
        >>> target = {'a': None}
        >>> glom(target, Fill('a', default='N/A'))
        'N/A'

    """
    def __init__(self, spec, default=None):
        self.spec = spec
        self.default = default

    def glomit(self, target, scope):
        ret = scope[glom](target, self.spec, scope)
        if ret is None:
            return self.default
        return ret

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, default=%r)' % (cn, self.spec, self.default)


class Iter(object):
    """Iter specifier type for iterating over iterables with options.

    Similar to using [] in specs but provides more control over iteration.

    Args:
       spec: The specification to iterate over. Defaults to T.
       max_depth: Maximum nesting depth for recursion.

    """
    def __init__(self, spec=T, max_depth=None):
        self.spec = spec
        self.max_depth = max_depth

    def glomit(self, target, scope):
        if self.spec is not T:
            target = scope[glom](target, self.spec, scope)
        try:
            iterate = scope[TargetRegistry].get_handler('iterate', target, path=scope[Path])
        except UnregisteredTarget:
            return [target]
        return list(iterate(target))

    def __repr__(self):
        cn = self.__class__.__name__
        if self.max_depth is None:
            return '%s(%r)' % (cn, self.spec)
        return '%s(%r, max_depth=%r)' % (cn, self.spec, self.max_depth)


class Let(object):
    """Let specifier type for creating local variable bindings in specs.

    Allows defining named values that can be referenced by other specs
    within the same Let block.

    Args:
       **bindings: Named specs to evaluate and bind locally.

    Example:
        >>> target = {'a': 1, 'b': 2}
        >>> glom(target, Let(x='a', y='b', sum=(T.x + T.y)))
        3

    """
    def __init__(self, **kwargs):
        self.bindings = kwargs

    def glomit(self, target, scope):
        # Evaluate each binding in order
        new_scope = dict(scope)
        for name, spec in self.bindings.items():
            new_scope[name] = scope[glom](target, spec, scope)
        # Return the target with updated scope
        # In glom 2.x, Let typically returns a dict of the bindings
        return {name: scope[glom](target, spec, new_scope) 
                for name, spec in self.bindings.items()}

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%s)' % (cn, ', '.join('%s=%r' % (k, v) for k, v in self.bindings.items()))


class Invoke(object):
    """Invoke specifier type for invoking/calling objects with arguments.

    Similar to Call but with additional support for constants and
    more flexible argument handling.

    Args:
       func: The callable to invoke.
       args: Positional arguments for the call.
       kwargs: Keyword arguments for the call.
       constants: Constants to include in the call scope (public attribute).

    Example:
        >>> class Obj:
        ...     def method(self, x, y):
        ...         return x + y
        >>> target = {'obj': Obj()}
        >>> glom(target, Invoke('obj.method', args=[1], kwargs={'y': 2}))
        3

    """
    def __init__(self, func, args=None, kwargs=None, constants=None):
        self.func = func
        self._args = args if args is not None else ()
        self._kwargs = kwargs if kwargs is not None else {}
        self.constants = constants if constants is not None else {}

    @property
    def consts(self):
        """Deprecated alias for constants."""
        return self.constants

    @consts.setter
    def consts(self, value):
        """Deprecated setter for constants."""
        self.constants = value

    def glomit(self, target, scope):
        def _eval(t):
            if type(t) in (Spec, TType):
                return scope[glom](target, t, scope)
            return t

        if type(self.func) is TType:
            func = _eval(self.func)
        else:
            func = self.func

        if type(self._args) is TType:
            args = _eval(self._args)
        else:
            args = [_eval(a) for a in self._args]

        if type(self._kwargs) is TType:
            kwargs = _eval(self._kwargs)
        else:
            kwargs = {name: _eval(val) for name, val in self._kwargs.items()}

        return func(*args, **kwargs)

    def __repr__(self):
        cn = self.__class__.__name__
        args_repr = repr(self._args) if self._args else '()'
        kwargs_repr = repr(self._kwargs) if self._kwargs else '{}'
        constants_repr = repr(self.constants) if self.constants else '{}'
        return '%s(%r, args=%s, kwargs=%s, constants=%s)' % (
            cn, self.func, args_repr, kwargs_repr, constants_repr)


